def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Last few moves
    last_my, last_op = history[-1]

    # Counts
    op_c = 0
    op_d = 0
    my_c = 0
    my_d = 0
    cc = 0
    cd = 0
    dc = 0
    dd = 0
    for m, o in history:
        if m == 'C':
            my_c += 1
        else:
            my_d += 1
        if o == 'C':
            op_c += 1
        else:
            op_d += 1
        if m == 'C' and o == 'C':
            cc += 1
        elif m == 'C' and o == 'D':
            cd += 1
        elif m == 'D' and o == 'C':
            dc += 1
        else:
            dd += 1

    op_rate = op_c / float(n)
    remaining = 100 - n

    # Early game: short cooperation probe, then respond.
    if n < 4:
        return 'C'

    # Opponent is almost always defecting: defect hard, rare probe.
    if op_rate <= 0.15:
        if n % 13 == 0:
            return 'C'
        return 'D'

    # Opponent is almost always cooperating: exploit, but not recklessly.
    if op_rate >= 0.90:
        if remaining <= 3:
            return 'D'
        # Probe occasionally; TFT-like punishers may retaliate.
        if op_d > 0 and dd > 0:
            # If mutual defection exists, play safe
            if n % 7 == 0:
                return 'D'
            return 'C'
        # Against likely unconditional cooperator, defect a bit more.
        if n >= 15 and n % 5 == 0:
            return 'D'
        return 'C'

    # Endgame: prefer defection when opponent likely cooperates.
    if remaining <= 2:
        if op_rate >= 0.6:
            return 'D'
        if last_op == 'D':
            return 'D'
        return 'D' if op_rate >= 0.4 else 'C'

    if remaining <= 6:
        if op_rate >= 0.55:
            return 'D'
        if last_op == 'D':
            return 'D'
        return 'C'

    # Detect sustained defection: many consecutive opponent Ds.
    consec_d = 0
    for m, o in reversed(history):
        if o == 'D':
            consec_d += 1
        else:
            break

    if consec_d >= 3:
        # Punish, but occasionally test forgiveness.
        if consec_d >= 6 and n % 11 == 0:
            return 'C'
        return 'D'

    # Detect sustained cooperation.
    consec_c = 0
    for m, o in reversed(history):
        if o == 'C':
            consec_c += 1
        else:
            break

    # If opponent has been very cooperative recently, cooperate, test rarely.
    recent = history[-8:] if n >= 8 else history
    recent_op_c = sum(1 for m, o in recent if o == 'C')
    recent_my_d = sum(1 for m, o in recent if m == 'D')

    if recent_op_c >= 7 and op_rate >= 0.65:
        # Controlled probing: defect occasionally to capture DC=5.
        if remaining > 10:
            if n % 9 == 0 and recent_op_c == 8:
                return 'D'
            if n % 17 == 0:
                return 'D'
        return 'C'

    # Tit-for-tat core with forgiveness.
    if last_op == 'C':
        # If we defected and they still cooperated, maybe exploit again.
        if last_my == 'D' and op_rate >= 0.5 and remaining > 8:
            if n % 3 == 0:
                return 'D'
        return 'C'

    # Opponent defected.
    # If opponent overall mostly cooperative, retaliate but forgive soon.
    if op_rate >= 0.55:
        if rng.random() < 0.40:
            return 'C'
        return 'D'

    # Opponent is mixed-leaning-defect.
    if op_rate >= 0.35:
        if recent_op_c >= 3 and rng.random() < 0.25:
            return 'C'
        return 'D'

    # Mostly defecting opponent.
    if n % 7 == 0:
        return 'C'
    return 'D'
